# --- 1) 플래그 출력 ---

$ for X in 256m 512m 1g; do
    java -Xmx$X -XX:+PrintFlagsFinal -version | grep -E 'MaxDirectMemorySize| MaxHeapSize '
  done
  -Xmx256m  MaxDirectMemorySize=0   (MaxHeapSize 256 MB)
  -Xmx512m  MaxDirectMemorySize=0   (MaxHeapSize 512 MB)
  -Xmx1g    MaxDirectMemorySize=0   (MaxHeapSize 1024 MB)

# 셋 다 0 이다. 이것만 보면 알 수 없다.

# --- 2) 잡아 본다 ---

$ cat Dlimit.java
public class Dlimit {
    public static void main(String[] a) {
        List<ByteBuffer> keep = new ArrayList<>();
        var bean = ManagementFactory.getPlatformMXBeans(BufferPoolMXBean.class)
            .stream().filter(b -> b.getName().equals("direct")).findFirst().orElse(null);
        try { for (;;) keep.add(ByteBuffer.allocateDirect(4 << 20)); }
        catch (OutOfMemoryError e) {
            System.out.printf("  한도 도달: %,d개 · %,d MB · count=%d%n",
                keep.size(), (long)keep.size()*4, bean.getCount());
        }
    }
}

$ java -Xmx256m -cp out Dlimit
  한도 도달: 64개 · 256 MB · count=64
$ java -Xmx512m -cp out Dlimit
  한도 도달: 128개 · 512 MB · count=128

# 정확히 -Xmx 만큼이다.

